package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// walkChanBound caps the Scan channel so a fast walk cannot memory-blow a slow
// core consumer; the core drains at store-write speed (natural backpressure).
// Same bound as plugins/base-scanner/walk.go.
const walkChanBound = 16

// videoMime maps a lowercased media extension to its MIME type. Replicated
// byte-for-byte from plugins/base-scanner/walk.go:25 (mediaMime) — episodes MUST
// be gated by the SAME extension set semantics as the shipped video walk
// (design.md D2 rule 2). A file whose extension is absent here is not video.
var videoMime = map[string]string{
	".mkv":  "video/x-matroska",
	".mp4":  "video/mp4",
	".m4v":  "video/x-m4v",
	".mov":  "video/quicktime",
	".avi":  "video/x-msvideo",
	".webm": "video/webm",
	".wmv":  "video/x-ms-wmv",
	".flv":  "video/x-flv",
	".mpg":  "video/mpeg",
	".mpeg": "video/mpeg",
	".ts":   "video/mp2t",
	".m2ts": "video/mp2t",
}

// structureSeriesDirectories is the ONLY accepted `structure` scanner option
// value (design.md §Interfaces §3); any other value is a fatal config error.
const structureSeriesDirectories = "series-directories"

// backingDirectory / backingFile are the `backing` marker-fact values
// (design.md §Interfaces §1).
const (
	backingDirectory = "directory"
	backingFile      = "file"
)

// matchSxxExx / matchBareNumber are the episode-linked match-basis values
// (design.md §Interfaces §2).
const (
	matchSxxExx     = "sxxexx"
	matchBareNumber = "bare_number"
)

// fileEntry is one discovered episode candidate: its library-relative path and
// absolute path.
type fileEntry struct {
	rel string
	abs string
}

// serialDirScan is the classification result for one depth-1 serial directory:
// its directly-contained episodes (sorted by rel), every sidecar found at any
// depth (sorted by rel), and the videos deeper than the serial dir's direct
// children (excluded from discovery, warned per serial dir — design.md D2 rule 3).
type serialDirScan struct {
	rel        string
	episodes   []fileEntry
	sidecars   []fileEntry
	deepVideos []string
}

// scanTree walks the resolved root ONE level deep (design.md D2 rule 1): each
// depth-1 subdirectory holding ≥1 directly-contained video file yields a serial
// record emitted BEFORE that directory's probed episodes; each loose top-level
// video file yields a file-backed serial record plus that file as its single
// probed episode (D2 rule 6). Entries matching neither the video nor the sidecar
// extension sets (extensionless smbdelete junk, .txt/.nfo, …) are excluded
// silently — no warning, no record (D2 rule 5). Directories holding no direct
// video (a sidecars-only folder, an empty dir) are not serials; their contents
// are skipped. ctx cancellation stops the walk and closes the channel.
func scanTree(ctx context.Context, s *scannerImpl, root string, out chan<- *scannerv1.DiscoveredFile) {
	entries, err := os.ReadDir(root)
	if err != nil {
		return // unreadable root: nothing to discover (soft, like the walk skip)
	}
	for _, entry := range entries {
		if ctx.Err() != nil {
			return
		}
		name := entry.Name()
		switch {
		case entry.IsDir():
			scanSerialDir(ctx, s, root, name, out)
		case entry.Type().IsRegular() && videoExt(name):
			// Loose top-level video → file-backed single-episode serial
			// (D2 rule 6): record first (with the probe JSON, Interfaces §4),
			// then the same file as the serial's single probed episode.
			emitFileBackedSerial(ctx, s, root, name, entry, out)
		default:
			// Junk (matches no extension set), symlinks, sockets: excluded
			// silently (D2 rule 5).
		}
	}
}

// scanSerialDir classifies one depth-1 subdirectory and, when it holds at least
// one directly-contained video file, emits its serial record BEFORE its
// episodes. The record's Warnings carry one entry per deeper video file, naming
// the serial and the unexpected file (D2 rule 3).
func scanSerialDir(ctx context.Context, s *scannerImpl, root, name string, out chan<- *scannerv1.DiscoveredFile) {
	scan := classifySerialDir(root, name)
	if len(scan.episodes) == 0 {
		return // no directly-contained video → not a serial
	}
	rel := scan.rel
	seriesSidecars, episodeSidecars := associateSidecars(scan)

	// Register the facts Identify will stamp BEFORE emitting anything: the core
	// identifies each file as the stream drains, starting with the record.
	facts := map[string]fileFacts{
		rel: {record: true, backing: backingDirectory, dirNameRaw: name, seriesRel: rel, seriesSidecars: seriesSidecars},
	}
	for i, ep := range scan.episodes {
		facts[ep.rel] = fileFacts{seriesRel: rel, sidecars: episodeSidecars[i]}
	}
	s.registerFacts(facts)

	record := &scannerv1.DiscoveredFile{
		FileId:       fileID(rel),
		RelativePath: rel,
		Warnings:     deepVideoWarnings(rel, scan.deepVideos),
	}
	if !emit(ctx, out, record) {
		return
	}
	for _, ep := range scan.episodes {
		if ctx.Err() != nil {
			return
		}
		if !emit(ctx, out, probedEpisode(ctx, root, ep)) {
			return
		}
	}
}

// classifySerialDir walks one depth-1 subdirectory recursively and sorts its
// direct video files, its sidecar files (any depth), and its deeper video files
// (excluded + warned, D2 rule 3) into a serialDirScan. Non-video non-sidecar
// entries are skipped silently (junk, D2 rule 5). Every candidate is re-verified
// by withinRoot before it is recorded (AC-4 defense in depth).
func classifySerialDir(root, name string) *serialDirScan {
	dirAbs := filepath.Join(root, name)
	scan := &serialDirScan{rel: name}
	_ = filepath.WalkDir(dirAbs, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil // skip unreadable entries rather than abort the walk
		}
		if d.IsDir() || !d.Type().IsRegular() {
			return nil
		}
		if !withinRoot(root, path) {
			return nil // AC-4: never read or probe a path that escapes root
		}
		relUnderSerial, relErr := filepath.Rel(dirAbs, path)
		if relErr != nil {
			return nil
		}
		entry := fileEntry{rel: filepath.Join(name, relUnderSerial), abs: path}
		switch {
		case videoExt(entry.rel):
			if relUnderSerial == filepath.Base(relUnderSerial) {
				scan.episodes = append(scan.episodes, entry) // direct child
			} else {
				scan.deepVideos = append(scan.deepVideos, entry.rel)
			}
		case sidecarExt(entry.rel):
			scan.sidecars = append(scan.sidecars, entry)
		default:
			// Junk: excluded silently (D2 rule 5).
		}
		return nil
	})
	sort.Slice(scan.episodes, func(i, j int) bool { return scan.episodes[i].rel < scan.episodes[j].rel })
	sort.Slice(scan.sidecars, func(i, j int) bool { return scan.sidecars[i].rel < scan.sidecars[j].rel })
	sort.Strings(scan.deepVideos)
	return scan
}

// associateSidecars classifies a serial dir's sidecars into series-level facts
// and per-episode facts (spec "Sidecar association"): SxxExx token in the
// sidecar filename first (matching an episode with the same season+episode),
// bare-number fallback when the sidecar has no SxxExx token, serial-level
// otherwise — never dropped silently. Returned slices are indexed in step with
// scan.episodes (the per-episode bucket) plus the series-level bucket.
func associateSidecars(scan *serialDirScan) (seriesLevel []sidecarFact, perEpisode [][]sidecarFact) {
	type epKey struct{ season, number int }
	byToken := map[epKey]int{}  // episode index by its SxxExx token
	byNumber := map[int][]int{} // episode indices by bare episode number
	perEpisode = make([][]sidecarFact, len(scan.episodes))
	for i, ep := range scan.episodes {
		stem := fileStem(ep.rel)
		if season, number, ok := seasonEpisodeOf(stem); ok {
			byToken[epKey{season, number}] = i
			byNumber[number] = append(byNumber[number], i)
		} else if n := bareNumberOf(stem); n > 0 {
			// An episode named without SxxExx (e.g. "ep1.mkv") is still
			// matchable by its bare number.
			byNumber[n] = append(byNumber[n], i)
		}
	}
	for _, sc := range scan.sidecars {
		stem := fileStem(sc.rel)
		parentName := filepath.Base(filepath.Dir(sc.rel))
		if parentName == "." || parentName == scan.rel {
			parentName = scan.rel // sidecar directly in the serial dir
		}
		language := sidecarLanguage(parentName, stem)
		idx, basis := -1, ""
		if season, number, ok := seasonEpisodeOf(stem); ok {
			if i, hit := byToken[epKey{season, number}]; hit {
				idx, basis = i, matchSxxExx
			}
		} else if n := bareNumberOf(stem); n > 0 {
			if candidates := byNumber[n]; len(candidates) > 0 {
				// Multiple seasons with the same episode number: the first
				// episode in sorted order wins (deterministic).
				idx, basis = candidates[0], matchBareNumber
			}
		}
		if idx < 0 {
			seriesLevel = append(seriesLevel, sidecarFact{
				RelativePath: sc.rel, Kind: sc.kind(), Language: language,
			}) // match_basis stays nil (serial-level, Interfaces §1)
			continue
		}
		matched := basis
		perEpisode[idx] = append(perEpisode[idx], sidecarFact{
			RelativePath: sc.rel, Kind: sc.kind(), Language: language, MatchBasis: &matched,
		})
	}
	return seriesLevel, perEpisode
}

// emitFileBackedSerial promotes one loose top-level video file to a file-backed
// single-episode serial (D2 rule 6): the record carries backing "file", the
// file's own relative path as series_relative_path, and the probe JSON
// (Interfaces §4); the same file is then emitted as the serial's single probed
// episode item. The file is probed ONCE and both emissions share the bytes.
func emitFileBackedSerial(ctx context.Context, s *scannerImpl, root, name string, entry fs.DirEntry, out chan<- *scannerv1.DiscoveredFile) {
	rel := name
	abs := filepath.Join(root, name)
	data, warning, _ := probe(ctx, abs) // soft-fail (AC-6); err always nil (INV3)
	var size int64
	if info, err := entry.Info(); err == nil {
		size = info.Size()
	}
	probeWarn := probeWarnings(warning)

	// The two emissions share ONE relative path, so the facts registry carries
	// a FIFO of views per rel and this registration order is the emission
	// order (record first, episode second — the drain identifies each
	// DiscoveredFile exactly once, in stream order): the record emission
	// identifies with the marker facts (PutSeries), the episode emission with
	// plain episode facts — seriesRel kept so the core stamps
	// series_relative_path; no SxxExx facts, so serial-parser is a skipped
	// stage. Marker facts on the episode view would route it as a SECOND
	// PutSeries and the serial would never get its single episode item
	// (spec "Loose top-level videos become file-backed serials", tasks 2.8,
	// D2 rule 6).
	s.registerFacts(map[string]fileFacts{
		rel: {record: true, backing: backingFile, dirNameRaw: name, seriesRel: rel},
	})
	s.registerFacts(map[string]fileFacts{
		rel: {seriesRel: rel},
	})

	record := &scannerv1.DiscoveredFile{
		FileId:       fileID(rel),
		RelativePath: rel,
		SizeBytes:    size,
		MimeType:     videoMime[strings.ToLower(filepath.Ext(rel))],
		FfprobeJson:  data,
	}
	if !emit(ctx, out, record) {
		return
	}
	episode := &scannerv1.DiscoveredFile{
		FileId:       fileID(rel),
		RelativePath: rel,
		SizeBytes:    size,
		MimeType:     videoMime[strings.ToLower(filepath.Ext(rel))],
		FfprobeJson:  data,
		Warnings:     probeWarn,
	}
	emit(ctx, out, episode)
}

// probedEpisode builds the DiscoveredFile for one episode video file, probed
// exactly like the base-scanner video walk (same extension set, same ffprobe
// invocation, same soft-fail semantics — design.md D2 rule 2).
func probedEpisode(ctx context.Context, root string, ep fileEntry) *scannerv1.DiscoveredFile {
	data, warning, _ := probe(ctx, ep.abs) // soft-fail (AC-6); err always nil (INV3)
	var size int64
	if info, err := os.Stat(ep.abs); err == nil {
		size = info.Size()
	}
	f := &scannerv1.DiscoveredFile{
		FileId:       fileID(ep.rel),
		RelativePath: ep.rel,
		SizeBytes:    size,
		MimeType:     videoMime[strings.ToLower(filepath.Ext(ep.rel))],
		FfprobeJson:  data,
	}
	if warning != "" {
		f.Warnings = []string{warning}
	}
	return f
}

// deepVideoWarnings returns one warning per unexpected deeper video file, each
// naming the serial and the file (D2 rule 3).
func deepVideoWarnings(serialRel string, deep []string) []string {
	if len(deep) == 0 {
		return nil
	}
	warnings := make([]string, 0, len(deep))
	for _, rel := range deep {
		warnings = append(warnings,
			"serial "+strconv.Quote(serialRel)+": unexpected deeper video file "+strconv.Quote(rel))
	}
	return warnings
}

// probeWarnings wraps a single probe soft-fail warning (nil when empty).
func probeWarnings(warning string) []string {
	if warning == "" {
		return nil
	}
	return []string{warning}
}

// emit sends one DiscoveredFile, honoring ctx cancellation. Reports whether the
// stream is still alive.
func emit(ctx context.Context, out chan<- *scannerv1.DiscoveredFile, f *scannerv1.DiscoveredFile) bool {
	select {
	case out <- f:
		return true
	case <-ctx.Done():
		return false
	}
}

// fileID returns a stable 16-hex-char id derived from the relative path
// (replicated from plugins/base-scanner/walk.go:129 — the join key the core
// persists before a full ULID is minted, scanner.proto).
func fileID(rel string) string {
	sum := sha256.Sum256([]byte(rel))
	return hex.EncodeToString(sum[:])[:16]
}

// videoExt reports whether path's lowercased dotted extension is a video
// extension (the mediaMime semantics — base-scanner extHas, walk.go:137).
func videoExt(path string) bool {
	_, ok := videoMime[strings.ToLower(filepath.Ext(path))]
	return ok
}

// sidecarExt reports whether path's lowercased dotted extension is a sidecar
// extension (design.md D2 rule 4 set).
func sidecarExt(path string) bool {
	_, ok := sidecarKind[strings.ToLower(filepath.Ext(path))]
	return ok
}

// kindOf returns the fact kind for a sidecar path ("subtitle"|"audio").
func (e fileEntry) kind() string {
	return sidecarKind[strings.ToLower(filepath.Ext(e.rel))]
}
